//! The icon tables of `wave.c`: ten ranges of the original program's data (vertices as three
//! floats, polygons as four corner numbers). None of it is in this source: each range is named by
//! its address and length in the Linux `soft` and read when first wanted, from the user's own
//! Softimage|3D 4.0 install (`si-rt`; release model: nothing of the original ships), checked
//! against our own checksum of it (`docs/design/runtime-data.md`). Generated by
//! `re/tools/si-scene/wave_tables.py`, which also holds this file against the program.

use si_rt::Table;
use std::sync::LazyLock;

/// Decodes a table of `R` rows of `N` little-endian words.
fn rows<const R: usize, const N: usize>(t: &Table) -> [[u32; N]; R] {
    let b = t.get();
    assert_eq!(b.len(), R * N * 4);
    let mut a = [[0u32; N]; R];
    for (i, c) in b.chunks_exact(4).enumerate() {
        a[i / N][i % N] = u32::from_le_bytes([c[0], c[1], c[2], c[3]]);
    }
    a
}

/// `wave_planar_vtx` (0x086d8760): 20 rows of 3 words.
pub static WAVE_PLANAR_VTX_TABLE: Table = Table::new("si_scene.wave_planar_vtx", 0x086d8760, 0xf0, 0x42d4_a4cd_1f75_65db);
pub static WAVE_PLANAR_VTX: LazyLock<[[u32; 3]; 20]> = LazyLock::new(|| rows(&WAVE_PLANAR_VTX_TABLE));

