#[cfg(test)]
mod tests {
    use super::*;

    /// With an install: every range is in the program, checks against its sum and decodes.
    #[test]
    fn tables_load() {
        si_rt::skip_without_install!();
        assert_eq!(WAVE_PLANAR_VTX.len(), 20);
        assert_eq!(WAVE_PLANAR_POLY.len(), 12);
        assert_eq!(WAVE_CIRCULAR_VTX.len(), 25);
        assert_eq!(WAVE_CIRCULAR_POLY.len(), 24);
        assert_eq!(WAVE_SPHERICAL_VTX.len(), 58);
        assert_eq!(WAVE_SPHERICAL_POLY.len(), 64);
        assert_eq!(WAVE_DRCTN_VTX.len(), 32);
        assert_eq!(WAVE_DRCTN_POLY.len(), 32);
        assert_eq!(WAVE_UP_VTX.len(), 27);
        assert_eq!(WAVE_UP_POLY.len(), 28);
    }
}

